class _EffectivePolicy(Dict[str, Any]):
    """Merged policy dict that is ALSO indexable by provenance dotpaths.

    The nested structure is preserved exactly (``p["convergence"]["v_comp_threshold"]``
    still works, ``p.keys()`` still yields section names), so existing consumers
    are unaffected. In addition, the flat dotpath keys used by ``provenance``
    resolve against the same object, so the two views of a ``PolicyResult`` can
    be joined on a single key.
    """

    def __getitem__(self, key: Any) -> Any:
        try:
            return super().__getitem__(key)
        except KeyError:
            if isinstance(key, str) and "." in key:
                value = _dotpath_get(self, key)
                if value is not _MISSING:
                    return value
            raise

    def __contains__(self, key: Any) -> bool:
        if super().__contains__(key):
            return True
        return (
            isinstance(key, str)
            and "." in key
            and _dotpath_get(self, key) is not _MISSING
        )

    def get(self, key: Any, default: Any = None) -> Any:
        try:
            return self[key]
        except KeyError:
            return default


